function questionsForKp(kpId) {
  return (TRAIN_QUESTION_BANKS.byKp[kpId] || []).map((q) => ({ ...q }))
}

function bankForTask(pathId, taskId) {
  const key = pathId + ':' + taskId
  return (TRAIN_QUESTION_BANKS.byTask[key] || []).map((q) => ({ ...q }))
}

module.exports = { TRAIN_QUESTION_BANKS, questionsForKp, bankForTask }
